package com.crm.employee.controller;
import com.crm.employee.entity.Employee; import com.crm.employee.repository.EmployeeRepository; import com.crm.common.response.ApiResponse; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/v1/employees") @RequiredArgsConstructor public class EmployeeController{private final EmployeeRepository repo;
@GetMapping public ApiResponse<List<Employee>> all(@RequestParam(required=false) Long companyId,@RequestParam(required=false) Long branchId,@RequestParam(required=false) Long departmentId){List<Employee>d=departmentId!=null?repo.findByDepartmentId(departmentId):(branchId!=null?repo.findByBranchId(branchId):(companyId!=null?repo.findByCompanyId(companyId):repo.findAll()));return ApiResponse.<List<Employee>>builder().success(true).message("Employees fetched").data(d).build();}
@GetMapping("/{id}") public ApiResponse<Employee> get(@PathVariable Long id){return ApiResponse.<Employee>builder().success(true).message("Employee fetched").data(repo.findById(id).orElseThrow(()->new IllegalArgumentException("Employee not found"))).build();}
@PostMapping @ResponseStatus(HttpStatus.CREATED) public ApiResponse<Employee> create(@Valid @RequestBody Employee e){if(repo.existsByEmployeeCode(e.getEmployeeCode()))throw new IllegalArgumentException("Employee code already exists");return ApiResponse.<Employee>builder().success(true).message("Employee created").data(repo.save(e)).build();}
@PutMapping("/{id}") public ApiResponse<Employee> update(@PathVariable Long id,@Valid @RequestBody Employee e){Employee x=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Employee not found"));x.setFirstName(e.getFirstName());x.setLastName(e.getLastName());x.setEmail(e.getEmail());x.setPhone(e.getPhone());x.setEmployeeCode(e.getEmployeeCode());x.setJoiningDate(e.getJoiningDate());x.setCompanyId(e.getCompanyId());x.setBranchId(e.getBranchId());x.setDepartmentId(e.getDepartmentId());x.setDesignationId(e.getDesignationId());x.setActive(e.isActive());return ApiResponse.<Employee>builder().success(true).message("Employee updated").data(repo.save(x)).build();}
@DeleteMapping("/{id}") public ApiResponse<Void> delete(@PathVariable Long id){repo.deleteById(id);return ApiResponse.<Void>builder().success(true).message("Employee deleted").build();}}